css:
.statecraftsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2433;
    background: linear-gradient(160deg, #eef1f6 0%, #e4e8f1 100%);
    border-radius: 18px;
}

.statecraftsim-container * {
    box-sizing: border-box;
}

.statecraftsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #11203d 0%, #1d3a63 55%, #2b4f87 100%);
    color: #f3f6fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(17, 32, 61, 0.32);
    border-bottom: 4px solid #c79a3a;
}

.statecraftsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.statecraftsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f1d79a;
    background: rgba(199, 154, 58, 0.18);
    padding: 5px 14px;
    border-radius: 999px;
}

.statecraftsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d9e1ef;
}

.statecraftsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #25406b;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.statecraftsim-period-counter #currentDay,
.statecraftsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #11203d;
}

.statecraftsim-round-name {
    background: #d3ddee;
    color: #11203d;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.statecraftsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a13;
    background: #f6e9cb;
    padding: 4px 12px;
    border-radius: 999px;
}

.statecraftsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.statecraftsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6deec;
    box-shadow: 0 4px 14px rgba(17, 32, 61, 0.07);
    border-top: 4px solid #2b4f87;
}

.statecraftsim-card-outcome { border-top-color: #1d6f5c; }
.statecraftsim-card-legit { border-top-color: #2b4f87; }
.statecraftsim-card-coalition { border-top-color: #6a4fb0; }
.statecraftsim-card-reputation { border-top-color: #c79a3a; }

.statecraftsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5e6b82;
}

.statecraftsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #11203d;
}

.statecraftsim-card-outcome .statecraftsim-value { color: #1d6f5c; }
.statecraftsim-card-legit .statecraftsim-value { color: #2b4f87; }
.statecraftsim-card-coalition .statecraftsim-value { color: #6a4fb0; }
.statecraftsim-card-reputation .statecraftsim-value { color: #b07f1c; }

.statecraftsim-sublabel {
    font-size: 0.76rem;
    color: #6f7c92;
    line-height: 1.35;
}

.statecraftsim-card-reputation.statecraftsim-rep-danger { border-top-color: #c0392b; }
.statecraftsim-card-reputation.statecraftsim-rep-danger .statecraftsim-value { color: #c0392b; }
.statecraftsim-card-outcome.statecraftsim-outcome-win { border-top-color: #1d6f5c; }
.statecraftsim-card-outcome.statecraftsim-outcome-win .statecraftsim-value { color: #14563f; }

.statecraftsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #11203d;
    color: #eaf0fa;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.statecraftsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f1d79a;
}

.statecraftsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c79a3a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(17, 32, 61, 0.06);
}

.statecraftsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.statecraftsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #11203d;
    margin-bottom: 6px;
}

.statecraftsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c3a52;
}

.statecraftsim-briefing-text strong { color: #1d6f5c; }
.statecraftsim-briefing-text em { color: #8a5a13; font-style: italic; }

.statecraftsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6deec;
    box-shadow: 0 4px 14px rgba(17, 32, 61, 0.07);
}

.statecraftsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #11203d;
    border-bottom: 2px solid #e4e8f1;
    padding-bottom: 8px;
}

.statecraftsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #23344f;
    margin: 14px 0 6px;
}

.statecraftsim-container select,
.statecraftsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcc8de;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7f9fd;
    color: #1c2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.statecraftsim-container select:focus,
.statecraftsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2b4f87;
    box-shadow: 0 0 0 3px rgba(43, 79, 135, 0.16);
}

.statecraftsim-container select option {
    background-color: #ffffff;
    color: #1c2433;
}

.statecraftsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c79a3a;
}

.statecraftsim-range-readout,
.statecraftsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #25406b;
    margin-top: 4px;
}

.statecraftsim-range-readout span:last-child,
.statecraftsim-alloc-readout span:nth-child(2) {
    color: #1d6f5c;
    font-weight: 800;
}

.statecraftsim-hint {
    font-size: 0.8rem;
    color: #6f7c92;
    margin-top: 4px;
    line-height: 1.4;
}

.statecraftsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.statecraftsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f2f5fb;
    border: 1px solid #dde4f0;
    border-radius: 9px;
    padding: 8px 12px;
}

.statecraftsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #23344f;
}

.statecraftsim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.statecraftsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.statecraftsim-container .btn-primary {
    background: linear-gradient(135deg, #1d3a63 0%, #2b4f87 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(29, 58, 99, 0.30);
}

.statecraftsim-container .btn-primary:hover {
    filter: brightness(1.10);
}

.statecraftsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcc8de;
    color: #5e6b82;
}

.statecraftsim-coach {
    background: #11203d;
    color: #eaf0fa;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(17, 32, 61, 0.24);
    border-left: 4px solid #c79a3a;
}

.statecraftsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f1d79a;
    margin-bottom: 8px;
}

.statecraftsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.statecraftsim-coach-body strong { color: #f1d79a; }
.statecraftsim-coach-body em { color: #f6c9a8; font-style: italic; }

.statecraftsim-history,
.statecraftsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6deec;
    box-shadow: 0 4px 14px rgba(17, 32, 61, 0.07);
}

.statecraftsim-history h3,
.statecraftsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #11203d;
}

.statecraftsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #23344f;
}

.statecraftsim-container table#usfHistoryTable th {
    background: #eaeef6;
    color: #11203d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4dcec;
}

.statecraftsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f8;
}

.statecraftsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fafd;
}

.statecraftsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .statecraftsim-container {
        padding: 14px;
    }
    .statecraftsim-header h1 {
        font-size: 1.7rem;
    }
    .statecraftsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .statecraftsim-value {
        font-size: 2rem;
    }
    .statecraftsim-clock {
        margin-left: 0;
    }
    .statecraftsim-period-counter {
        font-size: 0.88rem;
    }
    .statecraftsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .statecraftsim-alloc-row {
        flex-wrap: wrap;
    }
    .statecraftsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .statecraftsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

js:
(function() {
    'use strict';

    class StatecraftAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Engaging the State`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Hélios Énergie, France / EUR).
            this.BUDGET_CAP = 1.6;        // €1.6M non-market budget (fixed)
            this.OUTCOME_TARGET = 60;     // amendments secured to count as a real regulatory win
            this.LEGIT_TARGET = 58;       // standing with the regulator / public interest
            this.REP_FLOOR = 50;          // below this the €180M fair-price brand is materially damaged
            this.WIN_COMPOSITE = 68;      // joint optimisation of all four KPIs

            // Concept truths.
            this.TRUE_STANCE = `selective`;
            this.TRUE_LOGIC = `consumer`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    outcome: 18,
                    legitimacy: 25,
                    coalition: 22,
                    reputation: 60,
                    budgetUsed: 0,
                    escalated: false,
                    brandDamaged: false,
                    outcomeHistory: [18],
                    legitHistory: [25],
                    coalitionHistory: [22],
                    reputationHistory: [60],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a MIDDLING / neutral mix — never the textbook-correct play.
                state.decisions = {
                    stance: `selective`,
                    logic: `market`,
                    cap: `kill`,
                    rigour: 50,
                    frame: `technocratic`,
                    inside: 0.40,
                    outside: 0.40,
                    research: 0.40,
                    counsel: 0.40,
                    concede: 40,
                    posture: `join`,
                    ally: `none`,
                    incumbent: `accept`,
                    firewall: 50,
                    channel: `insideonly`,
                    submission: `margin`,
                    statement: `deflect`,
                    restraint: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const stance = document.getElementById(`stanceInput`);
                const logic = document.getElementById(`logicInput`);
                const cap = document.getElementById(`capInput`);
                const rig = document.getElementById(`rigourInput`);
                if (stance) decisions.stance = stance.value;
                if (logic) decisions.logic = logic.value;
                if (cap) decisions.cap = cap.value;
                if (rig) decisions.rigour = parseInt(rig.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const fr = document.getElementById(`frameInput`);
                if (fr) decisions.frame = fr.value;
                const inside = document.getElementById(`insideInput`);
                const outside = document.getElementById(`outsideInput`);
                const research = document.getElementById(`researchInput`);
                const counsel = document.getElementById(`counselInput`);
                if (inside) decisions.inside = parseFloat(inside.value);
                if (outside) decisions.outside = parseFloat(outside.value);
                if (research) decisions.research = parseFloat(research.value);
                if (counsel) decisions.counsel = parseFloat(counsel.value);
                const parts = [decisions.inside, decisions.outside, decisions.research, decisions.counsel];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.inside + decisions.outside + decisions.research + decisions.counsel) * 100) / 100;
                if (Math.abs(total - this.BUDGET_CAP) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
                const con = document.getElementById(`concedeInput`);
                if (con) decisions.concede = parseInt(con.value, 10);
                if (!Number.isFinite(decisions.concede) || decisions.concede < 0 || decisions.concede > 100) {
                    warn(`warn_concede_range`); return false;
                }
            } else if (round === 3) {
                const po = document.getElementById(`postureInput`);
                const al = document.getElementById(`allyInput`);
                const inc = document.getElementById(`incumbentInput`);
                const fw = document.getElementById(`firewallInput`);
                if (po) decisions.posture = po.value;
                if (al) decisions.ally = al.value;
                if (inc) decisions.incumbent = inc.value;
                if (fw) decisions.firewall = parseInt(fw.value, 10);
                if (!Number.isFinite(decisions.firewall) || decisions.firewall < 0 || decisions.firewall > 100) {
                    warn(`warn_firewall_range`); return false;
                }
            } else if (round === 4) {
                const ch = document.getElementById(`channelInput`);
                const su = document.getElementById(`submissionInput`);
                const st = document.getElementById(`statementInput`);
                const re = document.getElementById(`restraintInput`);
                if (ch) decisions.channel = ch.value;
                if (su) decisions.submission = su.value;
                if (st) decisions.statement = st.value;
                if (re) decisions.restraint = parseInt(re.value, 10);
                if (!Number.isFinite(decisions.restraint) || decisions.restraint < 0 || decisions.restraint > 100) {
                    warn(`warn_restraint_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let outcomeDelta = 0, legitDelta = 0, coalitionDelta = 0, repDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Read the field & triage the clauses (Common Error 2: total opposition).
                if (d.stance === `selective`) {
                    legitDelta += 8; outcomeDelta += 4; coachKey = `coach_r1_selective`;
                } else if (d.stance === `oppose`) {
                    // Fighting clauses you support triggers the Ministry's escalation.
                    legitDelta -= 8; outcomeDelta -= 4; repDelta -= 4; ds.escalated = true; coachKey = `coach_r1_oppose`;
                } else {
                    // Accepting everything quietly: brand safe, but you forfeit the €124M fight.
                    outcomeDelta -= 6; legitDelta += 1; coachKey = `coach_r1_accept`;
                }

                // Prevailing logic: influence runs through consumer-protection logic (Von Staden).
                if (d.logic === this.TRUE_LOGIC) {
                    legitDelta += 7;
                    if (d.stance === `selective`) coachKey = `coach_r1_sharp`;
                } else if (d.logic === `market`) {
                    legitDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r1_market` : coachKey;
                } else {
                    legitDelta -= 5; repDelta -= 1; coachKey = (coachKey === `coach_default`) ? `coach_r1_nologic` : coachKey;
                }

                // Clause-level position on the cap.
                if (d.cap === `amend`) {
                    outcomeDelta += 7; legitDelta += 2;
                } else if (d.cap === `kill`) {
                    outcomeDelta += 2; legitDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r1_kill` : coachKey;
                } else {
                    outcomeDelta -= 4;
                }

                // Evidence rigour underpins a credible position.
                if (d.rigour >= 60) { outcomeDelta += 4; legitDelta += 2; }
                else if (d.rigour <= 25) { outcomeDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r1_lowrigour` : coachKey; }

                summaryKey = (d.stance === this.TRUE_STANCE && d.logic === this.TRUE_LOGIC && d.cap === `amend`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Set the engagement strategy & frame (Common Errors 1 & 5).
                // Frame: shared-logic reframing wins; self-interest forfeits legitimacy.
                switch (d.frame) {
                    case `shared`: legitDelta += 9; outcomeDelta += 3; coachKey = `coach_r2_shared`; break;
                    case `selfinterest`: legitDelta -= 12; repDelta -= 5; outcomeDelta -= 2; coachKey = `coach_r2_selfinterest`; break;
                    case `technocratic`: legitDelta += 1; outcomeDelta += 1; coachKey = `coach_r2_technocratic`; break;
                }

                // Budget allocation across inside / outside / research / counsel.
                const inside = d.inside, outside = d.outside, research = d.research, counsel = d.counsel;
                spend = inside + outside + research + counsel;

                // Inside (submission + bilaterals) builds outcome; outside (public frame + customers)
                // builds legitimacy. A balanced inside+outside mix (the complementarity) is best;
                // dumping everything on one channel underperforms (Common Error 5 previewed here).
                outcomeDelta += Math.min(7, inside * 11);
                legitDelta += Math.min(7, outside * 11);
                const balanced = inside >= 0.3 && outside >= 0.3;
                if (balanced) { outcomeDelta += 2; legitDelta += 2; }
                else if (inside <= 0.1 || outside <= 0.1) { legitDelta -= 3; outcomeDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r2_unbalanced` : coachKey; }

                // Independent research lends credibility; some is valuable, hoarding it wastes budget.
                if (research >= 0.2 && research <= 0.6) { outcomeDelta += 3; legitDelta += 2; }
                else if (research > 0.6) { coachKey = (coachKey === `coach_default`) ? `coach_r2_overresearch` : coachKey; }
                // External counsel adds capability with sharply diminishing returns past ~€0.4M.
                if (counsel >= 0.2) outcomeDelta += 2;
                if (counsel > 0.6) { repDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_overcounsel` : coachKey; }

                // Public concession of supported clauses buys legitimacy (the price of standing).
                if (d.concede >= 60) { legitDelta += 5; outcomeDelta += 1; }
                else if (d.concede <= 20) { legitDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r2_noconcede` : coachKey; }

                summaryKey = (d.frame === `shared` && balanced) ? `sum_r2_good` : (d.frame === `selfinterest` ? `sum_r2_selfish` : `sum_r2_weak`);
            } else if (round === 3) {
                // Build the coalition (Common Errors 3 & 4).
                switch (d.posture) {
                    case `lead`: coalitionDelta += 14; outcomeDelta += 5; legitDelta += 2; coachKey = `coach_r3_lead`; break;
                    case `join`: coalitionDelta += 7; outcomeDelta -= 1; coachKey = `coach_r3_join`; break;
                    case `freeride`: coalitionDelta += 1; outcomeDelta -= 6; ds.escalated = true; coachKey = `coach_r3_freeride`; break;
                    case `solo`: coalitionDelta -= 5; outcomeDelta -= 3; coachKey = `coach_r3_solo`; break;
                }

                // Outside ally: a consumer group on the overlapping clauses is the high-legitimacy
                // move; the discount rivals are the TOXIC coalition that destroys the brand.
                switch (d.ally) {
                    case `consumer`: coalitionDelta += 8; legitDelta += 6; repDelta += 2; coachKey = (d.posture === `lead`) ? `coach_r3_consumer` : coachKey; break;
                    case `none`: coalitionDelta += 2; break;
                    case `discount`:
                        coalitionDelta += 9; legitDelta -= 9; repDelta -= 16; ds.brandDamaged = true; coachKey = `coach_r3_discount`; break;
                }

                // The incumbent's pact: accepting drops the SME disclosure relief you needed.
                if (d.incumbent === `reject`) { outcomeDelta += 4; }
                else { outcomeDelta -= 5; coalitionDelta += 3; coachKey = (coachKey === `coach_default` || coachKey === `coach_r3_join`) ? `coach_r3_incumbent` : coachKey; }

                // Reputational firewall against toxic allies (only meaningful if you took one).
                if (d.ally === `discount`) {
                    // Even a strong firewall only partly offsets allying with the rip-off suppliers.
                    repDelta += Math.round((d.firewall / 100) * 5);
                } else if (d.firewall >= 60) {
                    repDelta += 2;
                } else if (d.firewall <= 25) {
                    repDelta -= 3;
                }

                summaryKey = (d.posture === `lead` && d.ally === `consumer` && d.incumbent === `reject`) ? `sum_r3_good`
                    : (d.ally === `discount` ? `sum_r3_toxic` : (d.posture === `freeride` ? `sum_r3_freeride` : `sum_r3_weak`));
            } else if (round === 4) {
                // Execute the endgame & defend legitimacy (Common Error 5 + reputational trade-off).
                switch (d.channel) {
                    case `both`: outcomeDelta += 6; legitDelta += 6; coachKey = `coach_r4_both`; break;
                    case `insideonly`: outcomeDelta += 1; legitDelta -= 10; coachKey = `coach_r4_insideonly`; break;
                    case `outsideonly`: outcomeDelta += 2; legitDelta -= 4; repDelta -= 7; coachKey = `coach_r4_outsideonly`; break;
                }

                // Submission headline: the public-interest case lands; the margin case confirms the
                // hostile narrative (Common Error 1); a legal threat antagonises the regulator.
                switch (d.submission) {
                    case `public`: outcomeDelta += 7; legitDelta += 5; coachKey = (d.channel === `both`) ? `coach_r4_public` : coachKey; break;
                    case `margin`: outcomeDelta -= 3; legitDelta -= 8; repDelta -= 4; coachKey = `coach_r4_margin`; break;
                    case `legal`: outcomeDelta += 2; legitDelta -= 5; repDelta -= 3; coachKey = `coach_r4_legal`; break;
                }

                // Public statement to the hostile journalist — brand defence.
                switch (d.statement) {
                    case `owns`: legitDelta += 5; repDelta += 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_owns` : coachKey; break;
                    case `deflect`: repDelta -= 4; legitDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r4_deflect` : coachKey; break;
                    case `attack`: repDelta -= 10; legitDelta -= 6; ds.brandDamaged = true; coachKey = `coach_r4_attack`; break;
                }

                // Reputational restraint: holding back an aggressive campaign protects the brand
                // (Common Error 6 — winning amendments but tanking reputation).
                if (d.restraint >= 60) { repDelta += 5; }
                else if (d.restraint <= 25) { repDelta -= 5; coachKey = (coachKey === `coach_default`) ? `coach_r4_norestraint` : coachKey; }

                summaryKey = (d.channel === `both` && d.submission === `public` && d.statement === `owns`) ? `sum_r4_good`
                    : (d.submission === `margin` || d.statement === `attack` ? `sum_r4_selfish` : `sum_r4_weak`);
            }

            // Escalation penalty: an obstructive, self-interested campaign makes the Ministry
            // legislate directly — a harsher, non-negotiable statute that caps the outcome.
            if (ds.escalated) { outcomeDelta -= 3; legitDelta -= 2; }

            // Resource accounting (budget only spent in Round 2).
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;
            if (ds.budgetUsed > this.BUDGET_CAP) ds.budgetUsed = this.BUDGET_CAP;

            ds.outcome = Math.max(0, Math.min(100, ds.outcome + outcomeDelta));
            ds.legitimacy = Math.max(0, Math.min(100, ds.legitimacy + legitDelta));
            ds.coalition = Math.max(0, Math.min(100, ds.coalition + coalitionDelta));
            ds.reputation = Math.max(0, Math.min(100, ds.reputation + repDelta));

            if (ds.reputation < this.REP_FLOOR) ds.brandDamaged = true;

            ds.outcomeHistory.push(Math.round(ds.outcome));
            ds.legitHistory.push(Math.round(ds.legitimacy));
            ds.coalitionHistory.push(Math.round(ds.coalition));
            ds.reputationHistory.push(Math.round(ds.reputation));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                outcome: Math.round(ds.outcome),
                outcomeDelta: Math.round(outcomeDelta),
                legitimacy: Math.round(ds.legitimacy),
                legitDelta: Math.round(legitDelta),
                coalition: Math.round(ds.coalition),
                coalitionDelta: Math.round(coalitionDelta),
                reputation: Math.round(ds.reputation),
                repDelta: Math.round(repDelta),
                budgetUsed: ds.budgetUsed,
                escalated: ds.escalated,
                brandDamaged: ds.brandDamaged,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _money(v) {
