        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const outcome = Math.round(ds.outcome);
            const legitimacy = Math.round(ds.legitimacy);
            const coalition = Math.round(ds.coalition);
            const reputation = Math.round(ds.reputation);

            const wonOutcome = outcome >= this.OUTCOME_TARGET;
            const legitimate = legitimacy >= this.LEGIT_TARGET;
            const brandIntact = reputation >= this.REP_FLOOR;
            const composite = Math.round(outcome * 0.30 + legitimacy * 0.28 + coalition * 0.17 + reputation * 0.25);

            let performanceKey = `outmanoeuvred`;
            if (wonOutcome && legitimate && brandIntact && composite >= this.WIN_COMPOSITE) performanceKey = `institutional_entrepreneur`;
            else if (wonOutcome && brandIntact && legitimate) performanceKey = `credible_influence`;
            else if (wonOutcome && !brandIntact) performanceKey = `pyrrhic`;
            else if (legitimate && !wonOutcome) performanceKey = `legit_outvoted`;
            else if (ds.escalated) performanceKey = `triggered_statute`;
            // Stable, language-independent tier handle for the grading/reporting layer (read from domainState).
            ds.performanceTier = performanceKey;
            // Localized label for the debrief overlay (fixes English label leaking on non-EN screens).
            const performance = window.mySimulation.t(`tier_` + performanceKey);

            const insights = [];
            if (wonOutcome && legitimate && brandIntact) insights.push(window.mySimulation.t(`insight_win`));
            else if (wonOutcome && !brandIntact) insights.push(window.mySimulation.t(`insight_pyrrhic`));
            else if (!wonOutcome && ds.escalated) insights.push(window.mySimulation.t(`insight_escalated`));
            else if (!wonOutcome) insights.push(window.mySimulation.t(`insight_short`));

            if (!brandIntact) insights.push(window.mySimulation.t(`insight_brand`));
            if (legitimacy < this.LEGIT_TARGET) insights.push(window.mySimulation.t(`insight_legit`));
            if (coalition < 40) insights.push(window.mySimulation.t(`insight_coalition`));
            if (wonOutcome && legitimate && brandIntact && coalition >= 44) insights.push(window.mySimulation.t(`insight_jointly`));

            return {
                outcome: outcome,
                legitimacy: legitimacy,
                coalition: coalition,
                reputation: reputation,
                wonOutcome: wonOutcome,
                brandIntact: brandIntact,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.brandDamaged && ds.reputation < this.REP_FLOOR) return window.mySimulation.t(`hint_brand`);
            if (ds.escalated) return window.mySimulation.t(`hint_escalated`);
            if (ds.legitimacy < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_legit`);
            if (state.currentPeriod >= 3 && ds.outcome < 45) return window.mySimulation.t(`hint_behind`);
            if (ds.outcome >= this.OUTCOME_TARGET && ds.legitimacy >= this.LEGIT_TARGET && ds.reputation >= this.REP_FLOOR) return window.mySimulation.t(`hint_strong`);
            return null;
        }

